<div class="d-flex flex-wrap justify-content-between mb-3 gap-2"><h4 class="mb-0">Expiry &amp; Batches</h4><a class="btn btn-outline-secondary" href="<?= url('reports/view', ['report' => 'expiry']) ?>"><i class="bi bi-file-earmark-text"></i> Expiry report</a></div>
<div class="row g-3 mb-3"><div class="col-md-6"><div class="card border-danger"><div class="card-body"><div class="small text-muted">Expired stock (at cost)</div><div class="stat-value text-danger"><?= e(money($sum['expired_val'])) ?></div></div></div></div><div class="col-md-6"><div class="card border-warning"><div class="card-body"><div class="small text-muted">Expiring within <?= (int)$days ?> days (at cost)</div><div class="stat-value"><?= e(money($sum['soon_val'])) ?></div></div></div></div></div>
<form class="row g-2 mb-3" method="get"><input type="hidden" name="r" value="expiry/index"><div class="col-md-3"><select name="filter" class="form-select" data-autosubmit><?php foreach (['soon' => 'Expiring soon', 'expired' => 'Already expired', 'dated' => 'All dated batches', 'all' => 'All batches'] as $k => $l): ?><option value="<?= $k ?>" <?= $f === $k ? 'selected' : '' ?>><?= $l ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><select name="warehouse" class="form-select" data-autosubmit><option value="">All warehouses</option><?php foreach ($warehouses as $w): ?><option value="<?= (int)$w['id'] ?>" <?= $wh == $w['id'] ? 'selected' : '' ?>><?= e($w['name']) ?></option><?php endforeach; ?></select></div></form>
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead class="table-light"><tr><th>Product</th><th>Batch</th><th>Warehouse</th><th>Expiry</th><th class="text-end">Days left</th><th class="text-end">Qty</th><th class="text-end">Value (cost)</th><th class="text-end">Actions</th></tr></thead><tbody>
<?php foreach ($rows as $r): $d = $r['days_left']; $cls = $r['expiry_date'] === null ? 'secondary' : ($d < 0 ? 'danger' : ($d <= $days ? 'warning' : 'success')); ?>
<tr><td><?= link_product($r['product_id'], $r['sku'] . ' ' . $r['name']) ?></td><td><?= e($r['batch_no'] ?: '-') ?></td><td><?= link_wh($r['warehouse_id'], $r['wname']) ?></td><td><?= e($r['expiry_date'] ?: 'No expiry') ?></td><td class="text-end"><span class="badge text-bg-<?= $cls ?>"><?= $r['expiry_date'] === null ? '-' : ($d < 0 ? 'Expired ' . abs($d) . 'd ago' : $d . ' d') ?></span></td><td class="text-end"><?= fq($r['qty']) ?></td><td class="text-end"><?= number_format($r['qty'] * $r['cost_price'], 2) ?></td>
<td class="text-end text-nowrap"><?php if (Auth::can('inventory.expiry.markdown') && $r['expiry_date'] && $d >= 0): ?><form method="post" action="<?= url('expiry/markdown') ?>" class="d-inline-flex gap-1"><?= csrf_field() ?><input type="hidden" name="batch_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="filter" value="<?= e($f) ?>"><input type="number" name="percent" min="1" max="90" step="1" value="30" class="form-control form-control-sm" style="width:70px" title="Markdown %"><button class="btn btn-sm btn-outline-warning" title="Mark down at the POS until the expiry date"><i class="bi bi-tag"></i> Mark down</button></form><?php endif; ?>
<?php if (Auth::can('inventory.expiry.writeoff')): ?><form method="post" action="<?= url('expiry/writeoff') ?>" class="d-inline" data-confirm="Write off this batch (<?= e(fq($r['qty'])) ?>)? Stock will be reduced."><?= csrf_field() ?><input type="hidden" name="batch_id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="type" value="expired"><input type="hidden" name="filter" value="<?= e($f) ?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i> Write off</button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="text-center text-muted py-3">Nothing to show. Expiry dates are recorded when goods are received for products that have "Track batches and expiry dates" ticked.</td></tr><?php endif; ?></tbody></table></div></div>
